-- HelpToYou PostgreSQL schema. Run once against a new PostgreSQL database.
-- User ids are UUID strings generated by the Node API.

CREATE TABLE users (
  id UUID PRIMARY KEY,
  email TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  first_name VARCHAR(100) NOT NULL,
  last_name VARCHAR(100) NOT NULL,
  user_type VARCHAR(32) NOT NULL CHECK (user_type IN ('Student','Professor','Alumni','Sponsor','Volunteer','Applicant')),
  user_roles VARCHAR(32)[] NOT NULL DEFAULT ARRAY['Student']::VARCHAR(32)[]
    CHECK (cardinality(user_roles) BETWEEN 1 AND 6 AND user_roles <@ ARRAY['Student','Professor','Alumni','Sponsor','Volunteer','Applicant']::VARCHAR(32)[]),
  is_regional_lead BOOLEAN NOT NULL DEFAULT FALSE,
  is_verified BOOLEAN NOT NULL DEFAULT FALSE,
  university VARCHAR(255),
  department VARCHAR(255),
  designation VARCHAR(150),
  education_level VARCHAR(100),
  skills TEXT[] NOT NULL DEFAULT '{}',
  bio VARCHAR(2000),
  avatar_url VARCHAR(500),
  address1 VARCHAR(255),
  address2 VARCHAR(255),
  city VARCHAR(100),
  state VARCHAR(100),
  country VARCHAR(100),
  post_code VARCHAR(20),
  phone VARCHAR(30),
  mobile VARCHAR(30),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX users_email_lower_unique ON users (LOWER(email));

CREATE TABLE auth_sessions (
  id UUID PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX auth_sessions_user_id_idx ON auth_sessions(user_id);

CREATE TABLE help_requests (
  id UUID PRIMARY KEY,
  title VARCHAR(160) NOT NULL,
  description VARCHAR(5000) NOT NULL,
  category VARCHAR(50) NOT NULL CHECK (category IN ('Admissions','Research','Syllabus & Exam','Scholarships','Career Guidance','General Help')),
  university VARCHAR(160) NOT NULL,
  department VARCHAR(255),
  author_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  author_name VARCHAR(201) NOT NULL,
  author_role VARCHAR(32) NOT NULL,
  author_university VARCHAR(255),
  author_designation VARCHAR(150),
  urgency VARCHAR(20) NOT NULL DEFAULT 'Medium' CHECK (urgency IN ('Low','Medium','High')),
  status VARCHAR(20) NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','resolved')),
  tags TEXT[] NOT NULL DEFAULT '{}',
  response_count INTEGER NOT NULL DEFAULT 0 CHECK (response_count >= 0),
  upvotes INTEGER NOT NULL DEFAULT 0 CHECK (upvotes >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  resolved_at TIMESTAMPTZ
);
CREATE INDEX help_requests_feed_idx ON help_requests(created_at DESC, id DESC);
CREATE INDEX help_requests_author_idx ON help_requests(author_id, created_at DESC);
CREATE INDEX help_requests_category_status_idx ON help_requests(category, status, created_at DESC);

CREATE TABLE help_responses (
  id UUID PRIMARY KEY,
  request_id UUID NOT NULL REFERENCES help_requests(id) ON DELETE CASCADE,
  author_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  author_name VARCHAR(201) NOT NULL,
  author_role VARCHAR(32) NOT NULL,
  author_university VARCHAR(255),
  author_designation VARCHAR(150),
  content VARCHAR(5000) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX help_responses_thread_idx ON help_responses(request_id, created_at, id);

CREATE TABLE help_request_votes (
  request_id UUID NOT NULL REFERENCES help_requests(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (request_id, user_id)
);

CREATE TABLE connections (
  id UUID PRIMARY KEY,
  from_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  to_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  user_low UUID GENERATED ALWAYS AS (LEAST(from_user_id, to_user_id)) STORED,
  user_high UUID GENERATED ALWAYS AS (GREATEST(from_user_id, to_user_id)) STORED,
  status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','declined','cancelled')),
  message VARCHAR(2000),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CHECK (from_user_id <> to_user_id),
  UNIQUE (user_low, user_high)
);
CREATE INDEX connections_inbox_idx ON connections(to_user_id, status, created_at DESC);

CREATE TABLE blocked_users (
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  blocked_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, blocked_user_id),
  CHECK (user_id <> blocked_user_id)
);

CREATE TABLE reports (
  id UUID PRIMARY KEY,
  reporter_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  target_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reason VARCHAR(2000) NOT NULL,
  content_type VARCHAR(32) CHECK (content_type IN ('profile','help_request','response','message')),
  content_id UUID,
  status VARCHAR(20) NOT NULL DEFAULT 'open' CHECK (status IN ('open','reviewing','closed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CHECK (reporter_id <> target_user_id)
);
CREATE INDEX reports_status_created_idx ON reports(status, created_at);

CREATE TABLE chat_threads (
  id UUID PRIMARY KEY,
  participant_one UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  participant_two UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CHECK (participant_one < participant_two),
  UNIQUE (participant_one, participant_two)
);

CREATE TABLE chat_messages (
  id UUID PRIMARY KEY,
  thread_id UUID NOT NULL REFERENCES chat_threads(id) ON DELETE CASCADE,
  sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  text VARCHAR(5000) NOT NULL,
  is_read BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX chat_messages_thread_idx ON chat_messages(thread_id, created_at, id);

CREATE TABLE notifications (
  id UUID PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type VARCHAR(60) NOT NULL,
  title VARCHAR(160) NOT NULL,
  message VARCHAR(1000) NOT NULL,
  data JSONB NOT NULL DEFAULT '{}',
  is_read BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX notifications_user_feed_idx ON notifications(user_id, created_at DESC);

CREATE TABLE push_tokens (
  token TEXT PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  platform VARCHAR(20) NOT NULL CHECK (platform IN ('ios','android','web')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE institutions (
  id UUID PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  location VARCHAR(255) NOT NULL,
  institution_type VARCHAR(50) NOT NULL DEFAULT 'University',
  departments TEXT[] NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (name, location)
);

CREATE TABLE contact_messages (
  id UUID PRIMARY KEY,
  name VARCHAR(200) NOT NULL,
  email VARCHAR(255) NOT NULL,
  subject VARCHAR(200) NOT NULL,
  message VARCHAR(5000) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'Received' CHECK (status IN ('Received','In Review','Responded')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX contact_messages_created_idx ON contact_messages(created_at DESC);
